#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> H(N), leftMax(N), rightMax(N);

    for (int i = 0; i < N; i++) {
        cin >> H[i];
    }

    long long cur = 0;
    for (int i = 0; i < N; i++) {
        cur = max(cur, H[i]);
        leftMax[i] = cur;
    }

    cur = 0;
    for (int i = N - 1; i >= 0; i--) {
        cur = max(cur, H[i]);
        rightMax[i] = cur;
    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        long long waterLevel = min(leftMax[i], rightMax[i]);
        if (waterLevel - H[i] >= 1) {
            ans++;
        }
    }

    cout << ans << '\n';
    return 0;
}
